package com.paytrace.integrity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="invariant_results") public class InvariantResultEntity { @Id private UUID id; @Column(name="payment_id",nullable=false) private UUID paymentId; @Column(name="invariant_name",nullable=false) private String invariantName; @Column(nullable=false) private boolean passed; @Column(nullable=false) private String evidence; @Column(name="evaluated_at",nullable=false) private Instant evaluatedAt; protected InvariantResultEntity(){} public InvariantResultEntity(UUID paymentId,InvariantResult r){id=UUID.randomUUID();this.paymentId=paymentId;invariantName=r.name();passed=r.passed();evidence=r.evidence();evaluatedAt=Instant.now();} public String invariantName(){return invariantName;} public boolean passed(){return passed;} public String evidence(){return evidence;} }
